function readLocal<T,>(key:string,fallback:T):T{try{const value=localStorage.getItem(key);return value?JSON.parse(value) as T:fallback}catch{return fallback}}
function Logo(){return <Link className="brand brand-image" to="/" aria-label="AutoVault home"><img src="/autovault-logo.png" alt="AutoVault"/></Link>}
function StudioPhoto({src,alt,className}:{src:string;alt:string;className:string}){const [failed,setFailed]=useState(!src);useEffect(()=>setFailed(!src),[src]);return failed?<div className={`${className} studio-photo-placeholder`} role="img" aria-label={`${alt}; no verified studio photo available`}><span>PHOTO NOT PUBLISHED</span></div>:<img className={className} src={src} alt={alt} loading="lazy" onError={()=>setFailed(true)}/>}
