function Footer(){return <footer className="footer"><div className="footer-main"><div><Logo/><p>Every car. Every service.<br/>Every detail — simplified.</p></div><div><b>Explore</b><Link to="/discover">Find a service</Link><Link to="/garage">My garage</Link><Link to="/business/register">List your business</Link></div><div><b>Company</b><Link to="/contact">Contact us</Link><Link to="/privacy">Privacy</Link><Link to="/terms">Terms</Link></div><div><b>Stay in the know</b><p>Good car care, straight to your inbox.</p><form className="subscribe" onSubmit={e=>{e.preventDefault();alert('Thanks for joining the AutoVault list.')}}><input placeholder="Your email address" type="email" required/><button aria-label="Subscribe"><ArrowRight size={17}/></button></form></div></div><div className="footer-bottom"><span>© 2026 AutoVault Technologies</span><span>Made for the road ahead. <span className="orange">●</span></span></div></footer>}
