function App(){const [loading,setLoading]=useState(false);const timeout=useRef<ReturnType<typeof setTimeout>|null>(null);useEffect(()=>{const onAction=(event:MouseEvent)=>{const target=event.target;if(!(target instanceof Element))return;const action=target.closest<HTMLElement>('button:not(:disabled),a[href^="/"],input[type="checkbox"],select,[role="button"]');if(!action)return;setLoading(true);if(timeout.current)clearTimeout(timeout.current);timeout.current=setTimeout(()=>setLoading(false),1000)};document.addEventListener('click',onAction,true);return()=>{document.removeEventListener('click',onAction,true);if(timeout.current)clearTimeout(timeout.current)}},[]);return <><Header/><Routes><Route path="/" element={<Navigate to="/discover" replace/>}/><Route path="/home" element={<Home/>}/><Route path="/discover" element={<Discover/>}/><Route path="/business/:id/services" element={<StudioServicesPage/>}/><Route path="/business/:id" element={<BusinessPage/>}/><Route path="/compare" element={<Compare/>}/><Route path="/garage" element={<Garage/>}/><Route path="/login" element={<Navigate to="/" replace/>}/><Route path="/signup" element={<Navigate to="/" replace/>}/><Route path="/forgot-password" element={<Navigate to="/" replace/>}/><Route path="/offers" element={<Simple title="Offers worth the drive" desc="Thoughtful ways to take better care of your car."/>}/><Route path="/diagnose" element={<DiagnosePage/>}/><Route path="/dashboard" element={<Dashboard/>}/><Route path="/ai" element={<AIPage/>}/><Route path="/business/register" element={<Simple title="Bring your business to AutoVault" desc="Meet more car owners and manage your bookings in one place."/>}/><Route path="/contact" element={<Simple title="We’re here to help" desc="Questions about finding a service or bringing your business onboard? Say hello at hello@autovault.in."/>}/><Route path="/privacy" element={<Policy title="Privacy Policy"/>}/><Route path="/terms" element={<Policy title="Terms and Conditions"/>}/><Route path="*" element={<NotFound/>}/></Routes><Footer/><BottomNavigation/>{loading&&<SpeedometerLoader/>}</>}
