  {id:'pentagon',title:'CrystalShield Pentagon 10H',price:'₹26,950–₹29,950',duration:'Free paint inspection available',warranty:'Confirm package warranty with studio',coverage:'Exterior paint; confirm inclusions',prep:'Book the free paint inspection',highlights:['Hatchback ₹26,950','Sedan ₹27,950','Luxury/SUV ₹29,950']},
  {id:'impact',title:'CrystalShield 10 Impact',price:'₹34,950–₹39,950',duration:'Free paint inspection available',warranty:'Confirm package warranty with studio',coverage:'Exterior paint; confirm inclusions',prep:'Book the free paint inspection',highlights:['Hatchback ₹34,950','Sedan ₹37,950','Luxury/SUV ₹39,950']}
