 return [{id:'studio-quote',title:`${service} package`,price:'Contact for quote',duration:'Confirm with studio',warranty:'Confirm package terms',coverage:'Confirm service coverage',prep:'Inspection and preparation details vary by vehicle',highlights:['Ask for the package inclusions','Final pricing depends on vehicle and selected work','Call the studio to confirm availability']}]
